      UserId(
        _nonBlank(
          values[index],
          '$path[$index]',
          ConversationCreationParseErrorCode.malformedMemberId,
        ),
      ),
    );
  }
  return _uniqueUserIds(ids, path);
}

List<UserId> _uniqueUserIds(List<UserId> values, String path) {
  final result = <UserId>[];
  final seen = <String>{};
  for (var index = 0; index < values.length; index += 1) {
    final member = _memberId(values[index], '$path[$index]');
    if (!seen.add(member.value)) {
      throw _creationError(
        ConversationCreationParseErrorCode.duplicateMemberId,
        '$path cannot contain duplicate member ID ${member.value}',
      );
    }
    result.add(member);
  }
  return result;
}

UserId _memberId(UserId value, String path) => UserId(
      _nonBlank(
        value.value,
        path,
        ConversationCreationParseErrorCode.malformedMemberId,
      ),
    );

bool _sameIds(List<UserId> left, List<UserId> right) =>
    left.length == right.length &&
    left.indexed.every((entry) => entry.$2 == right[entry.$1]);

String _inputId(Map<String, Object?> object, String field) => _nonBlank(
      object[field],
      'input.$field',
      ConversationCreationParseErrorCode.malformedInput,
    );

ConversationVisibility _visibility(
  Object? value,
  String path,
  ConversationCreationParseErrorCode code,
) {
  try {
    return ConversationVisibility.fromJson(value);
  } on FormatException {
    throw _creationError(code, '$path must be public or private');
  }
}

void _rejectTrustedIdentityFields(Object? value, [String path = 'input']) {
  if (value is List<Object?>) {
    for (var index = 0; index < value.length; index += 1) {
      _rejectTrustedIdentityFields(value[index], '$path[$index]');
    }
    return;
  }
  if (value is! Map<Object?, Object?>) return;
  for (final entry in value.entries) {
    if (entry.key is! String) {
      throw _creationError(
        ConversationCreationParseErrorCode.malformedInput,
        '$path keys must be strings',
      );
    }
    final key = entry.key! as String;
    final normalized = key.replaceAll(RegExp('[^a-zA-Z0-9]'), '').toLowerCase();
    if (_trustedIdentityFields.contains(normalized)) {
      throw _creationError(
        ConversationCreationParseErrorCode.trustedIdentityField,
        '$path.$key is server-derived and cannot be supplied by a client',
      );
    }
    _rejectTrustedIdentityFields(entry.value, '$path.$key');
  }
}

Map<String, Object?> _object(
  Object? value,
  String path,
  ConversationCreationParseErrorCode code,
) {
  if (value is! Map<Object?, Object?>) {
    throw _creationError(code, '$path must be a JSON object');
  }
  final result = <String, Object?>{};
  for (final entry in value.entries) {
    if (entry.key is! String) {
      throw _creationError(code, '$path keys must be strings');
    }
    result[entry.key! as String] = entry.value;
  }
  return result;
}

void _allowed(
  Map<String, Object?> object,
  Set<String> allowed,
  String path,
  ConversationCreationParseErrorCode code,
) {
  for (final key in object.keys) {
    if (!allowed.contains(key)) {
      throw _creationError(code, '$path.$key is not supported');
    }
  }
}

String _nonBlank(
  Object? value,
  String path,
  ConversationCreationParseErrorCode code,
) {
  if (value is! String || value.trim().isEmpty) {
    throw _creationError(code, '$path must be a nonblank string');
  }
  return value;
}

ConversationCreationFormatException _creationError(
  ConversationCreationParseErrorCode code,
  String message,
) =>
    ConversationCreationFormatException(code, message);
